    /// <inheritdoc />
    protected override Blake2b CreateAlgorithm(Blake2bVariant variant) =>
        variant switch
        {
            Blake2bVariant.Blake2b_128 => new Blake2b(128),
            Blake2bVariant.Blake2b_160 => new Blake2b(160),
            Blake2bVariant.Blake2b_192 => new Blake2b(192),
